const tokens = require('fs').readFileSync(0, 'utf8').trim().split(/\s+/);
const n = parseInt(tokens[0], 10);

// Representa o preço P exatamente em centavos (P * 100) usando inteiros
let bp = -1, bg = 1; // melhor preço (centavos) e gramas correspondentes

for (let i = 0; i < n; i++) {
  const p = Math.round(parseFloat(tokens[1 + 2 * i]) * 100);
  const g = parseInt(tokens[2 + 2 * i], 10);
  // compara p/g < bp/bg por multiplicação cruzada (exato, sem ponto flutuante)
  if (bp < 0 || p * bg < bp * g) {
    bp = p;
    bg = g;
  }
}

// custo por kg em centavos = (bp/100) * (1000/bg) * 100 = bp * 1000 / bg
const num = bp * 1000;
const den = bg;

// arredondamento para 2 casas decimais feito com aritmética inteira exata:
// cents = round(num/den) = floor((2*num + den) / (2*den))
const cents = Math.floor((2 * num + den) / (2 * den));

const intPart = Math.floor(cents / 100);
const frac = String(cents % 100).padStart(2, '0');

process.stdout.write(intPart + '.' + frac + '\n');
